import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets")
public class SheetController {

    /** A sheet as the screen shows it; lastBatch is the number of its last bulk settle batch, null for none. */
    public record SheetView(String id, LocalDate today, boolean archived, Integer lastBatch) {
        public static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.isArchived(),
                    sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch());
        }
    }

    public record TodayChange(@NotNull LocalDate today) {
    }

    private final SheetService service;

    public SheetController(SheetService service) {
        this.service = service;
    }

    /** Load a sheet by id, starting it empty if it was never loaded before. */
    @PutMapping("/{id}")
    @ViewerPasses
    @AsOfReads
    public SheetView load(@PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String id) {
        return SheetView.of(service.load(id));
    }

    /** Change the sheet's today. */
    @PutMapping("/{id}/today")
    public SheetView setToday(@PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String id,
            @Valid @RequestBody TodayChange change, @SessionAttribute(SessionController.USER) String user) {
        return SheetView.of(service.setToday(user, id, change.today()));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Loads a sheet by id; a sheet never loaded before starts empty. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;
    private final ApplicationEventPublisher events;

    public SheetService(SheetRepository sheets, RollupService rollup, ApplicationEventPublisher events) {
        this.sheets = sheets;
        this.rollup = rollup;
        this.events = events;
    }

    public Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> create(id));
    }

    /**
     * Change the sheet's today; every date decision on the sheet follows it. It has no audit line of its own, only
     * the figures it moves, after a SNAPSHOT line per person with their due-total on the day being left. What follows
     * a today change (the periods it closes) runs before those are rolled up.
     */
    @Transactional
    public Sheet setToday(String by, String id, LocalDate today) {
        Sheet sheet = load(id);
        RollupService.Snapshot before = rollup.snapshot(id);
        rollup.recordSnapshot(by, id, before);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        events.publishEvent(new TodayChanged(by, saved));
        rollup.recordChanges(by, id, before);
        return saved;
    }

    /** Loads the sheet and locks it until the transaction ends, so changes checked against the whole sheet run in turn. */
    @Transactional
    public Sheet lock(String id) {
        load(id);
        return sheets.findWithLockById(id).orElseThrow();
    }

    /** Takes the sheet's next claim number; two callers at once never get the same one. */
    @Transactional
    public long nextClaimNumber(String id) {
        load(id);
        sheets.incrementClaimNumber(id);
        return sheets.lastClaimNumber(id);
    }

    /** Takes the sheet's next settle batch number; two callers at once never get the same one. */
    @Transactional
    public int nextSettleBatch(String id) {
        load(id);
        sheets.incrementSettleBatch(id);
        return sheets.lastSettleBatch(id);
    }

    private Sheet create(String id) {
        try {
            return sheets.saveAndFlush(new Sheet(id));
        } catch (DataIntegrityViolationException e) {
            // another user created it at the same moment
            return sheets.findById(id).orElseThrow(() -> e);
        }
    }
}
