}
package net.officefloor.hq.app.asof;


/**
 * Once a request that may change a sheet has gone through, stores the state the sheet now stands in (see
 * {@link AsOfService#capture}). The answer is held back until it is stored, so the next change, which the screen makes
 * only once it has the answer, never comes first.
 */
@Component
public class SnapshotFilter extends OncePerRequestFilter {

    private static final Logger LOG = LoggerFactory.getLogger(SnapshotFilter.class);

    /** A request on a sheet: /api/sheets/{id}, and anything under it. */
    private static final Pattern SHEET = Pattern.compile("^/api/sheets/([A-Za-z0-9_.-]+)(?:/.*)?$");

    private final AsOfService asOf;

    public SnapshotFilter(AsOfService asOf) {
        this.asOf = asOf;
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        String method = request.getMethod();
        return HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)
                || sheetId(request) == null;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        ContentCachingResponseWrapper held = new ContentCachingResponseWrapper(response);
        try {
            chain.doFilter(request, held);
            String header = request.getHeader(AsOfGuard.HEADER);
            // a request answered as of a date changes nothing
            if (held.getStatus() < 400 && (header == null || header.isBlank())) {
                try {
                    asOf.capture(sheetId(request));
                } catch (RuntimeException e) {
                    LOG.error("Could not store the state of sheet {}", sheetId(request), e);
                }
            }
        } finally {
            held.copyBodyToResponse();
        }
    }

    private static String sheetId(HttpServletRequest request) {
        Matcher m = SHEET.matcher(request.getRequestURI().substring(request.getContextPath().length()));
        return m.matches() ? m.group(1) : null;
    }
}
package net.officefloor.hq.app.asof;


/**
 * A screen showing a sheet as of a date sends that date with each request ({@link #HEADER}). Such a request is
 * answered from the sheet as it stood at the end of the date (see {@link AsOfService#storeAsOf}), and every request
 * that changes the sheet is refused before it reaches its handler, so it writes nothing. A handler marked
 * {@link AsOfReads} changes nothing and is answered as of the date.
 */
@Component
public class AsOfGuard implements HandlerInterceptor {

    /** The request header carrying the date the screen shows the sheet as of (yyyy-mm-dd). */
    public static final String HEADER = "X-As-Of";

    private final AsOfService asOf;

    public AsOfGuard(AsOfService asOf) {
        this.asOf = asOf;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String header = request.getHeader(HEADER);
        String sheetId = ViewerGuard.sheetId(request);
        if (header == null || header.isBlank() || !(handler instanceof HandlerMethod method) || sheetId == null) {
            return true;
        }
        LocalDate day;
        try {
            day = LocalDate.parse(header.trim());
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The as-of date is not a date.");
        }
        if (!HttpMethod.GET.matches(request.getMethod()) && !method.hasMethodAnnotation(AsOfReads.class)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The sheet is shown as of a date; nothing on it can change.");
        }
        AsOfContext.enter(asOf.storeAsOf(sheetId, day));
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler,
            Exception ex) {
        AsOfContext.leave();
    }
}

